style.css:
@-moz-document domain("roblox.com"), url-prefix("https://www.roblox.com/home"), url-prefix("https://www.roblox.com/") {
:root {
        --black: #0a0a0a;
        --orange: #ff4c00;
    }

    /* === TŁO === */
    body, #app, .container-fluid, .content, .main,
    .main-content, .game-grid, .discover-page, .home-content {
        background: var(--black) !important;
        color: var(--orange) !important;
    }

    /* Navbar */
    #navigation, nav, .rbx-navbar-header, .top-bar {
        background: #000000 !important;
        border-bottom: 2px solid var(--orange) !important;
    }

    /* Sidebar */
    #left-navigation, .sidebar, .left-col, .navigation-menu {
        background: #000000 !important;
        border-right: 3px solid var(--orange) !important;
    }

    /* === LOGO → Roblox Hub === */
    #nav-logo-link {
        font-size: 0 !important;
        background: var(--orange) !important;
        padding: 6px 14px !important;
        border-radius: 8px !important;
        display: inline-flex !important;
        align-items: center !important;
        text-decoration: none !important;
        border: none !important;
        box-shadow: none !important;
    }

    #nav-logo-link .icon-logo,
    #nav-logo-link .icon-logo-r {
        display: none !important;
    }

    #nav-logo-link::before {
        content: "Roblox " !important;
        font-size: 18px !important;
        color: #ffffff !important;
        font-weight: 700 !important;
    }

    #nav-logo-link::after {
        content: "Hub" !important;
        font-size: 18px !important;
        color: #000000 !important;
        font-weight: 700 !important;
    }

    #nav-logo-link:hover {
        background: var(--orange) !important;
        opacity: 0.9 !important;
    }

    /* === SEARCH === */
    .rbx-navbar-search,
    .navbar-search,
    #navbar-search-input,
    input[type="search"] {
        background: #111111 !important;
        border: 2px solid var(--orange) !important;
        color: var(--orange) !important;
        border-radius: 8px !important;
    }

    #navbar-search-input::placeholder,
    input[type="search"]::placeholder {
        color: #ff7a00 !important;
        opacity: 1 !important;
    }

    /* === NAPISY === */
    h2, h3, p, span, label,
    .text-label, .game-card-name,
    .friends-carousel-tile-name,
    .friends-carousel-display-name,
    .section-header, .username, .profile-name {
        color: var(--orange) !important;
    }

    a, .link {
        color: var(--orange) !important;
    }

    a:hover {
        color: #ff7a00 !important;
    }

    /* === IKONY NAVBAR — bez pomarańczowego tła === */
    #navigation a,
    #navigation button,
    nav a,
    nav button,
    .rbx-navbar-header a,
    .rbx-navbar-header button,
    .shopping-cart-btn-container a,
    .shopping-cart-btn-container button {
        background: transparent !important;
        border: none !important;
        box-shadow: none !important;
    }

    #navigation a:hover,
    #navigation button:hover,
    nav a:hover,
    nav button:hover,
    .rbx-navbar-header a:hover,
    .rbx-navbar-header button:hover,
    .shopping-cart-btn-container a:hover,
    .shopping-cart-btn-container button:hover {
        background: transparent !important;
        color: var(--orange) !important;
        box-shadow: none !important;
    }

    /* === KARTY === */
    .game-card, .thumbnail-container, .avatar-card,
    .friend-tile, .card {
        background: #111111 !important;
        border: 2px solid var(--orange) !important;
        border-radius: 10px !important;
    }

    .game-card:hover {
        border-color: #ff7a00 !important;
        box-shadow: 0 0 15px rgba(255, 76, 0, 0.4) !important;
    }

    /* Bez podświetlenia znajomych */
    .friend-tile:hover,
    .avatar-card:hover,
    .friends-carousel-tile:hover {
        background: #111111 !important;
        border-color: var(--orange) !important;
        box-shadow: none !important;
    }

    /* === PRZYCISKI (poza navbar) === */
    .main-content button,
    .main-content .btn,
    .home-content button,
    .home-content .btn,
    .game-grid button,
    .game-grid .btn {
        background: #111111 !important;
        border-color: var(--orange) !important;
        color: var(--orange) !important;
    }

    .main-content button:hover,
    .main-content .btn:hover,
    .home-content button:hover,
    .home-content .btn:hover {
        background: var(--orange) !important;
        color: #000000 !important;
    }

    /* Scrollbar */
    ::-webkit-scrollbar {
        background: var(--black) !important;
    }

    ::-webkit-scrollbar-thumb {
        background: var(--orange) !important;
    }

    /* Reklamy */
    .ad-container, .sponsored, .promoted {
        display: none !important;
    }
}
